"""Generate the static documentation site and attach the locally built release."""
from pathlib import Path
import hashlib
import html
import shutil
from theme import STYLE, SCRIPT, decorate

ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'dist'
OUT.mkdir(exist_ok=True)
release = ROOT.parent / 'release/WoodSetup.exe'
launcher = ROOT.parent / 'release/WoodLauncher.exe'
packager = ROOT.parent / 'release/WoodModPackager.exe'
if not release.is_file() or not launcher.is_file() or not packager.is_file():
    raise FileNotFoundError('Build WoodSetup.exe, WoodLauncher.exe, and WoodModPackager.exe before generating the download site.')
checksum = hashlib.sha256(release.read_bytes()).hexdigest() if release.exists() else 'Build the release to generate a checksum.'
launcher_checksum = hashlib.sha256(launcher.read_bytes()).hexdigest()
packager_checksum = hashlib.sha256(packager.read_bytes()).hexdigest()
size = f'{release.stat().st_size / 1024 / 1024:.1f} MB' if release.exists() else 'Build required'
launcher_size = f'{launcher.stat().st_size / 1024 / 1024:.1f} MB'

