admin = page('Curator publishing.', 'Publish mods to the live collection. Only someone with the private Netlify token can submit releases.', '''<section class="token-guide" aria-labelledby="token-title"><p class="eyebrow">Curator setup</p><h2 id="token-title">Where do I get the token?</h2><p><strong>You create it yourself.</strong> Netlify does not issue a curator token automatically. Generate a private random value, then save the same value in your Netlify site's environment variables as <code>MOD_ADMIN_TOKEN</code>.</p><ol class="token-steps"><li><strong>Generate a secret on your computer.</strong> Open PowerShell and run this once:</li></ol><pre class="token-command"><code>$bytes = New-Object byte[] 32
$rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$rng.GetBytes($bytes)
$token = [Convert]::ToBase64String($bytes).TrimEnd('=').Replace('+','-').Replace('/','_')
Set-Clipboard -Value $token
$rng.Dispose()</code></pre><p class="form-help">This copies a fresh 256-bit secret to your clipboard. Keep it private; do not paste it into chat, source files, or a public issue.</p><ol class="token-steps" start="2"><li><strong>Save it in Netlify.</strong> Open your Netlify site → <strong>Site configuration → Environment variables</strong>. Add <code>MOD_ADMIN_TOKEN</code>, paste the clipboard value as its value, and make it available to Functions.</li><li><strong>Redeploy the site.</strong> The function reads the environment variable when running. Redeploy after adding or rotating the token.</li><li><strong>Paste the same token below</strong> when publishing. The page sends it to the API in an Authorization header and does not save it in browser storage.</li></ol><p class="token-note"><strong>Not deployed yet?</strong> The token field will not work on a local static preview. First deploy the project with Netlify CLI and configure <code>MOD_ADMIN_TOKEN</code>. If the token is lost or exposed, generate another and replace the Netlify value.</p></section><form id="publish-form" class="form-panel admin-form"><div class="form-section"><h2>Access</h2><p class="form-help">Your token is required for every submission and is never stored by this page.</p><div class="form-field"><label for="admin-token">Private curator token</label><input id="admin-token" name="admin_token" type="password" autocomplete="new-password" placeholder="Paste your MOD_ADMIN_TOKEN value" aria-describedby="token-help" required><span id="token-help" class="form-help">Use the value you generated and added in Netlify.</span></div></div><div class="form-section"><h2>Mod details</h2><div class="form-grid"><div class="form-field"><label for="mod-id">Mod ID</label><input id="mod-id" name="id" pattern="[a-z0-9-]+" minlength="2" maxlength="40" placeholder="my-mod" required></div><div class="form-field"><label for="mod-name">Display name</label><input id="mod-name" name="name" minlength="2" maxlength="80" required></div><div class="form-field"><label for="mod-author">Author</label><input id="mod-author" name="author" value="Wood" minlength="2" maxlength="60" required></div><div class="form-field"><label for="mod-version">Version</label><input id="mod-version" name="version" placeholder="1.0.0" pattern="[0-9]+\\.[0-9]+\\.[0-9]+(-[A-Za-z0-9.-]+)?" required></div><div class="form-field full"><label for="mod-summary">Short summary</label><input id="mod-summary" name="summary" minlength="10" maxlength="180" required></div><div class="form-field full"><label for="mod-description">Details</label><textarea id="mod-description" name="description" minlength="10" maxlength="2000" required></textarea></div><div class="form-field"><label for="game-version">TUNG version</label><input id="game-version" name="game_version" maxlength="80" value="Current Steam release" required></div><div class="form-field"><label for="mod-tags">Tags</label><input id="mod-tags" name="tags" maxlength="128" placeholder="Practice, Utilities"></div><div class="form-field full"><label for="mod-changelog">Version notes</label><textarea id="mod-changelog" name="changelog" maxlength="1000"></textarea></div><div class="form-field full"><label for="lua-file">Lua source (.lua, max 1 MiB)</label><input id="lua-file" name="lua_file" type="file" accept=".lua,text/plain" required></div></div><p class="form-help">Use a new version number for updates; the same mod ID and version cannot be published twice.</p><button id="publish-submit" class="btn" type="submit">Publish mod</button><p id="publish-status" class="form-status" role="status" aria-live="polite"></p></div></form>''')
live_split = page('Set up LiveSplit.', 'Install the community autosplitter, load the supplied TUNG layout, and time the supported Any% route.', '''<div class="downloadbox"><span class="tag">Community autosplitter · Windows</span><h2>TUNG LiveSplit files</h2><p>Includes only the ASL script, supplied splits and layout, and a launcher that updates file paths for your computer. The Coordinates mod is a separate download.</p><div class="actions"><a class="btn" href="downloads/TUNG-LiveSplit-Autosplitter.zip" download>Download autosplitter ↓</a><a class="btn secondary" href="mods.html">Coordinates mod</a></div><p class="micro">Requires LiveSplit for Windows, the Scriptable Auto Splitter component, and Wood with Coordinates enabled for the Hedge split.</p></div><h2>Install and start</h2><ol><li>Install LiveSplit and open it once. In Edit Layout, add <strong>Control → Scriptable Auto Splitter</strong> if it is not already present.</li><li>Install Wood Setup, then download the separate <strong>Coordinates</strong> mod from the official mod collection if it is not already installed.</li><li>Extract the autosplitter ZIP to a permanent, writable folder. Do not run it from inside the ZIP.</li><li>Double-click <code>Launch-TUNG-LiveSplit.cmd</code> and select your <code>LiveSplit.exe</code>. The launcher connects the script, layout, and splits to their current file locations.</li><li>In Scriptable Auto Splitter settings, enable <strong>Start</strong>, <strong>Split</strong>, and <strong>Reset</strong>. Keep <strong>Synchronize Game Time with TUNG's speedrun timer</strong> enabled.</li><li>The supplied timer and split columns use Game Time. Right-click the timer and select <strong>Compare Against → Game Time</strong>.</li><li>In TUNG, use normal Speedrun mode. Disable Tiny Tung and bhop, do not use a checkpoint, let LiveSplit see the main menu, then select New Game.</li></ol><h2>Included Any% segments</h2><ol><li>Valves unlocked</li><li>Valve 1</li><li>Valve 2</li><li>Valve 3</li><li>Valve 4</li><li>Door</li><li>Hedge</li><li>Finish</li></ol><p>Valves may be collected in any order. The Hedge split requires the separate Coordinates mod to export live player coordinates; the autosplitter archive does not contain or install that mod. If an intermediate event is missed, finishing still ends the run and skipped times remain blank. Save the run under your own filename to preserve PBs.</p><div class="callout">The Hedge trigger uses the supplied grounded-landing capture to define an observed position band. It still needs confirmation in a fresh live run; the trace alone does not establish the full hedge bounds.</div><h2>Known limitations</h2><p>The autosplitter accepts only the tested TUNG Steam build and executable hash documented in its included README. Checkpoint loads, Tiny Tung, bhop, and other game builds are unsupported. Game Time follows TUNG's speedrun clock and its pause/loading behavior.</p><p>If LiveSplit was already running, open the supplied split file with <strong>Open Splits → From File</strong> and the layout with <strong>Open Layout → From File</strong>. If the folder is moved, rerun the launcher to repair its file paths.</p>''')
for name, title, body in [('index.html','Native modding. Your pace.',home),('downloads.html','Downloads',downloads),('guides.html','Guides',guides),('mods.html','Official Mods',mods),('admin.html','Curator Publishing',admin),('live-split.html','LiveSplit Setup',live_split),('developers.html','Developers',developers),('about.html','About',about)]:
    body = decorate(name, body, demo)
    (OUT / name).write_text(shell(name, title, body), encoding='utf-8')
(OUT / 'style.css').write_text(CSS + STYLE, encoding='utf-8')
(OUT / 'catalog.css').write_text((ROOT / 'catalog.css').read_text(encoding='utf-8'), encoding='utf-8')
(OUT / 'mods.js').write_text((ROOT / 'mods.js').read_text(encoding='utf-8'), encoding='utf-8')
(OUT / 'mods-admin.js').write_text((ROOT / 'mods-admin.js').read_text(encoding='utf-8'), encoding='utf-8')
(OUT / 'mods.json').unlink(missing_ok=True)
(OUT / 'mods').mkdir(exist_ok=True)
for old_mod in (OUT / 'mods').glob('*.lua'):
    old_mod.unlink()
(OUT / 'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="6" fill="#111b25"/>'+LOGO.split('>',1)[1].rsplit('</svg>',1)[0]+'</svg>')
(OUT / 'site.js').write_text('''const slider=document.querySelector('#speed-range');if(slider){const output=document.querySelector('#speed');const buttons=[...document.querySelectorAll('[data-speed]')];function update(value){slider.value=value;output.value=Number(value).toFixed(2);buttons.forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.speed)===Number(value))));}slider.addEventListener('input',()=>update(slider.value));buttons.forEach(button=>button.addEventListener('click',()=>update(button.dataset.speed)));}''')
(OUT / 'site.js').write_text((OUT / 'site.js').read_text(encoding='utf-8') + SCRIPT, encoding='utf-8')
if release.exists():
    (OUT / 'downloads').mkdir(exist_ok=True)
    shutil.copy2(release, OUT / 'downloads/WoodSetup.exe')
    shutil.copy2(launcher, OUT / 'downloads/WoodLauncher.exe')
    shutil.copy2(packager, OUT / 'downloads/WoodModPackager.exe')
    shutil.copy2(ROOT.parent / 'release/SHA256SUMS.txt', OUT / 'downloads/SHA256SUMS.txt')
autosplitter = ROOT.parents[1] / 'TUNG-LiveSplit-Autosplitter-main'
if autosplitter.is_dir():
    import zipfile
    import xml.etree.ElementTree as ET
    (OUT / 'downloads').mkdir(exist_ok=True)
    with zipfile.ZipFile(OUT / 'downloads/TUNG-LiveSplit-Autosplitter.zip', 'w', zipfile.ZIP_DEFLATED) as bundle:
        for filename in ('TUNG.asl', 'TUNG.lsl', 'TUNG-AnyPercent.lss',
                         'Launch-TUNG-LiveSplit.cmd', 'Launch-TUNG-LiveSplit.ps1', 'README.md'):
            source = autosplitter / filename
            if filename in ('TUNG.lsl', 'TUNG-AnyPercent.lss'):
                document = ET.parse(source)
                if filename == 'TUNG.lsl':
                    for component in document.findall('.//Component'):
                        path = component.find('Path')
                        script_path = component.find('./Settings/ScriptPath')
                        if path is not None and path.text == 'LiveSplit.ScriptableAutoSplit.dll' and script_path is not None:
                            script_path.text = 'TUNG.asl'
                else:
                    layout_path = document.find('.//LayoutPath')
                    if layout_path is not None:
                        layout_path.text = 'TUNG.lsl'
                bundle.writestr(filename, ET.tostring(document.getroot(), encoding='utf-8', xml_declaration=True))
            else:
                bundle.write(source, filename)
shutil.copy2(ROOT / 'headers.txt', OUT / '_headers')
print(f'Site generated: {OUT}')
